/* A creator's payments connection can be reset without losing what it was: stripe_previous_account_id (the connected account Storelib was linked to before), stripe_account_reset_at (when that link was let go) and stripe_account_reset_reason (legacy_platform when Stripe says the account is not reachable from the current platform, which is what happens to every creator linked before Storelib moved to its new Stripe Connect platform; creator_disconnect when the creator chose Start over; incomplete_replaced when an unfinished account was swapped for one that stays inside Storelib). The live link stays stripe_account_id, which is cleared so the creator can set up a fresh account under the current platform instead of being stuck on one Storelib can no longer read. Orders, payouts, refunds and the ledger are never touched: each keeps the Stripe ids it was written with. Only the server writes these three, and they are private like the other Stripe columns (parts 63 and 77): the private list and the guard trigger are restated in full with them added. Safe to run more than once. Until it runs, a reset still happens and the old account id is written to the server log instead. */
DO $$ BEGIN IF to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'stripe account reset: there is no creators table, nothing to do.'; ELSE ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_previous_account_id text; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_account_reset_at timestamptz; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_account_reset_reason text; ALTER TABLE public.creators DROP CONSTRAINT IF EXISTS creators_stripe_account_reset_reason_check; ALTER TABLE public.creators ADD CONSTRAINT creators_stripe_account_reset_reason_check CHECK (stripe_account_reset_reason IS NULL OR stripe_account_reset_reason IN ('legacy_platform','creator_disconnect','incomplete_replaced')); END IF; END $$;
CREATE OR REPLACE FUNCTION public.storelib_private_columns(p_table text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $f$ SELECT CASE p_table WHEN 'creators' THEN ARRAY['stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'payout_currency', 'payout_schedule', 'payout_threshold', 'instant_payouts_enabled', 'banned_reason', 'statement_descriptor', 'first_sale_email_sent', 'stripe_requirements', 'stripe_requirements_due_at', 'stripe_requirements_updated_at', 'payments_status', 'last_stripe_sync_at', 'stripe_previous_account_id', 'stripe_account_reset_at', 'stripe_account_reset_reason'] WHEN 'profiles' THEN ARRAY['email', 'role', 'spam_state', 'spam_score', 'personalized_recommendations', 'timezone', 'push_messages_enabled', 'push_preview_enabled', 'first_name', 'last_name', 'address_line1', 'address_line2', 'city', 'state', 'postal_code', 'country', 'phone', 'date_of_birth', 'tax_id'] ELSE ARRAY[]::text[] END $f$;
DO $do$ BEGIN IF to_regclass('public.creators') IS NOT NULL AND to_regprocedure('public.storelib_keep_server_columns()') IS NOT NULL THEN DROP TRIGGER IF EXISTS creators_keep_server_columns ON public.creators; CREATE TRIGGER creators_keep_server_columns BEFORE INSERT OR UPDATE ON public.creators FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_server_columns('user_id', 'stripe_account_id', 'stripe_customer_id', 'stripe_subscription_id', 'stripe_connected_at', 'stripe_onboarding_status', 'details_submitted', 'charges_enabled', 'payouts_enabled', 'subscription_plan_id', 'subscription_status', 'pending_plan_id', 'paypal_merchant_id', 'banned_at', 'banned_reason', 'first_sale_email_sent', 'reviews_average', 'reviews_count', 'views', 'featured', 'stripe_requirements', 'stripe_requirements_due_at', 'stripe_requirements_updated_at', 'payments_status', 'last_stripe_sync_at', 'stripe_previous_account_id', 'stripe_account_reset_at', 'stripe_account_reset_reason'); END IF; END $do$;
DO $do$ BEGIN IF to_regprocedure('public.storelib_share_public_columns()') IS NOT NULL THEN PERFORM public.storelib_share_public_columns(); END IF; END $do$;
notify pgrst, 'reload schema';
